function showPublishUpgrade(siteId,d){setView('billing');const box=$('#billingMsg');const recommended=String(d.recommended_plan||'STARTER').toUpperCase();const purchasable=['STARTER','GROWTH'].includes(recommended)?recommended:null;const planLabel=purchasable?purchasable[0]+purchasable.slice(1).toLowerCase():'an eligible plan';box.innerHTML=`<div class="publish-upgrade"><b>${purchasable?`Upgrade to ${escapeHtml(planLabel)}`:'Choose an eligible plan'} to publish this ${Number(d.page_count)||''}-page template site</b><p>${escapeHtml(d.message||'Template page limits depend on the selected plan. AI-created website page count continues to follow the business brief.')}</p>${purchasable?`<div class="form-actions"><button class="accent-btn" data-publish-upgrade="${purchasable}">Activate ${escapeHtml(planLabel)}</button></div>`:''}</div>`;const b=$('[data-publish-upgrade]',box);if(b)b.onclick=async()=>{b.disabled=true;const ok=await upgradePaid(purchasable,true);if(ok)await publishFromDashboard(siteId);else b.disabled=false}}
