function renderTemplates(){const g=$('#templateGrid');if(!g)return;if(!state.templates.length){g.innerHTML=`<div class="dashboard-empty-template"><span>0 templates</span><h2>Catalogue review in progress.</h2><p>Only independently verified templates are published here.</p><a class="accent-btn" href="/ai-create">Create with AI</a></div>`;return}g.innerHTML=state.templates.map(t=>`<article class="template-item"><div class="template-preview"><img src="${escapeHtml(t.preview||'')}" alt="Rendered preview of ${escapeHtml(t.name)}" loading="lazy"></div><h3>${escapeHtml(t.name)}</h3><p class="template-kicker">${escapeHtml(t.industry||t.category||'Website')} · ${Number(t.pages||1)} page${Number(t.pages||1)===1?'':'s'}</p><p class="template-description">${escapeHtml(t.description||t.art_direction||'Purpose-built website template.')}</p><div class="template-actions"><a href="/template-preview/${encodeURIComponent(t.slug)}" target="_blank" rel="noopener">Preview</a><button type="button" data-template-use="${escapeHtml(t.slug)}">Use template</button></div></article>`).join('');$$('[data-template-use]').forEach(b=>b.onclick=()=>{location.href=`/signup?template=${encodeURIComponent(b.dataset.templateUse)}`})}

