async function unlockSourceExport(siteId){try{let direct=await fetch(`/api/sites/${siteId}/export`,{credentials:'same-origin'});if(direct.ok){const blob=await direct.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='zylora-nextjs.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);return}const err=await direct.json().catch(()=>({}));if(direct.status!==402)throw new Error(err.detail?.message||err.detail||'Export unavailable');const cfg=await api('/api/source-export/config'),currency='USD',price=(cfg.prices[currency]||0)/100;if(!confirm(`Standalone Next.js source export costs ${new Intl.NumberFormat(undefined,{style:'currency',currency}).format(price)}. Ownership transfer remains free. Continue?`))return;const o=await api(`/api/sites/${siteId}/source-export/order`,{method:'POST',body:JSON.stringify({currency})});if(o.entitled){location.href=`/api/sites/${siteId}/export`;return}if(o.provider==='mock'){await api(`/api/sites/${siteId}/source-export/verify`,{method:'POST',body:JSON.stringify({order_id:o.order_id,payment_id:o.mock_payment_id,signature:o.mock_signature})});toast('Source export unlocked');location.href=`/api/sites/${siteId}/export`;return}await loadRazorpay();const rz=new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,order_id:o.order_id,name:'Zylora',description:'Next.js source export',prefill:{name:state.me.name,email:state.me.email},handler:async r=>{await api(`/api/sites/${siteId}/source-export/verify`,{method:'POST',body:JSON.stringify({order_id:r.razorpay_order_id,payment_id:r.razorpay_payment_id,signature:r.razorpay_signature})});location.href=`/api/sites/${siteId}/export`}});rz.open()}catch(e){toast(e.message)}}
async function loadGrowth(){try{const j=await api(`/api/growth?days=${Number(state.analyticsRange||30)}`),t=j.totals||{},af=j.assistant||{};$('#growthVisitors')&&($('#growthVisitors').textContent=t.visitors||0);$('#growthViews')&&($('#growthViews').textContent=`${t.page_views||0} page views`);$('#growthConversion')&&($('#growthConversion').textContent=`${Number(t.lead_conversion_rate||0).toFixed(1)}%`);$('#growthCtaRate')&&($('#growthCtaRate').textContent=`${Number(t.cta_rate||0).toFixed(1)}% CTA rate`);$('#assistantOpened')&&($('#assistantOpened').textContent=af.opened||0);$('#assistantMeaningful')&&($('#assistantMeaningful').textContent=af.meaningful_conversations||0);$('#assistantLeads')&&($('#assistantLeads').textContent=af.leads_captured||0);$('#assistantQualified')&&($('#assistantQualified').textContent=af.qualified_leads||0);$('#assistantHot')&&($('#assistantHot').textContent=af.hot_leads||0);$('#assistantAppointments')&&($('#assistantAppointments').textContent=af.appointments_booked||0);$('#assistantFunnelCount')&&($('#assistantFunnelCount').textContent=af.leads_captured||0);$('#assistantFunnelRate')&&($('#assistantFunnelRate').textContent=`${Number(af.conversion_rate||0).toFixed(1)}% conversion`);const insights=$('#growthInsights');if(insights)insights.innerHTML=(j.insights||[]).map(x=>`<div class="stack-item"><div><b>${escapeHtml(x.title||x.code)}</b><small>${escapeHtml(x.detail||'')}</small></div>${x.action==='AI_OPTIMIZE_CTA'&&j.sites?.[0]?`<a class="ghost-btn" href="/editor/${j.sites[0].id}?ai=${encodeURIComponent('Improve conversion and CTA clarity using the current website design system. Preserve the brand direction.')}">Fix with AI</a>`:''}</div>`).join('')||'<p class="muted-copy">No recommendations yet. More traffic data will make this view more useful.</p>';const pages=$('#growthPages');if(pages)pages.innerHTML=(j.pages||[]).slice(0,10).map(x=>`<div class="stack-item"><div><b>${escapeHtml(x.path)}</b><small>${x.views} views · ${x.cta_clicks} CTA clicks</small></div><span class="status-badge">${Number(x.cta_rate||0).toFixed(1)}%</span></div>`).join('')||'<p class="muted-copy">No tracked page views yet.</p>'}catch(e){toast(e.message)}}
async function loadHealth(){const sel=$('#healthSite');if(!sel)return;if(!sel.options.length)fillSiteSelectors();const siteId=sel.value||state.sites?.[0]?.id;if(!siteId){$('#healthStatus').textContent='Create a website first';return}try{const [h,a]=await Promise.all([api(`/api/sites/${siteId}/health`),api(`/api/audit?site_id=${encodeURIComponent(siteId)}&limit=20`)]),qa=h.launch?.qa||{};$('#healthScore').textContent=`${h.score??0}/100`;$('#healthStatus').textContent=h.status||'UNKNOWN';$('#healthBlockers').textContent=qa.blocking_count||0;$('#healthWarnings').textContent=qa.warning_count||0;$('#healthChecklist').innerHTML=(h.launch?.items||[]).map(x=>`<div class="stack-item"><div><b>${x.status==='PASS'?'✓':x.status==='BLOCKED'?'!':'△'} ${escapeHtml(x.label)}</b><small>${escapeHtml(x.detail||'')}</small></div><span class="status-badge">${escapeHtml(x.status)}</span></div>`).join('');$('#healthComponents').innerHTML=Object.entries(h.components||{}).map(([k,v])=>`<div class="stack-item"><div><b>${escapeHtml(k.replaceAll('_',' '))}</b><small>${escapeHtml(v.status||'')}</small></div><span class="status-badge">${escapeHtml(v.status||'')}</span></div>`).join('');const rec=h.components?.recoverability?.latest_backup;$('#healthBackupMeta').textContent=rec?`Latest: ${rec.label||rec.reason} · ${new Date(rec.created_at).toLocaleString()}`:'No restore point exists yet.';const dc=h.components?.lead_delivery?.counts||{};$('#healthDeliveryMeta').textContent=`Sent ${dc.SENT||0} · Failed ${dc.FAILED||0} · Dead-letter ${dc.DEAD_LETTER||0}`;$('#healthAudit').innerHTML=(a.items||[]).map(x=>`<div class="stack-item"><div><b>${escapeHtml(x.action.replaceAll('_',' '))}</b><small>${escapeHtml(new Date(x.created_at).toLocaleString())}</small></div></div>`).join('')||'<p class="muted-copy">No audit activity yet.</p>'}catch(e){toast(e.message)}}
