async function loadBillingRecovery(){const box=$('#billingRecoveryList');if(!box)return;try{const j=await api('/api/billing/recovery'),items=j.items||[];box.innerHTML=items.length?items.map(x=>`<div class="stack-item"><div><b>${escapeHtml(x.order_kind.replaceAll('_',' '))}</b><small>${escapeHtml(x.local_order_id)} · ${x.attempt_count} reconciliation attempt(s)${x.last_error?' · '+escapeHtml(x.last_error):''}</small></div><button class="ghost-btn" data-reconcile-payment="${x.id}">Reconcile</button></div>`).join(''):'<p class="muted-copy">No unresolved payment cases.</p>';$$('[data-reconcile-payment]').forEach(b=>b.onclick=async()=>{try{await api(`/api/billing/recovery/${b.dataset.reconcilePayment}/reconcile`,{method:'POST'});toast('Payment state reconciled');loadBillingRecovery();loadBilling()}catch(e){toast(e.message)}})}catch(e){box.innerHTML=`<p class="muted-copy">${escapeHtml(e.message)}</p>`}}
async function loadBilling(){const [j,topups,history]=await Promise.all([api('/api/billing'),api('/api/billing/credit-topups'),api('/api/billing/history')]);const offers=j.regional_offers||{},sub=j.subscription||null;$$('.billing-grid article[data-plan]').forEach(a=>a.classList.toggle('current',a.dataset.plan===j.plan));$('#creditCount').textContent=j.ai_credits;$('#leadCreditCount').textContent=j.lead_credits??'—';renderCreditDensity(j.credit_wallet);$('#aCredits')&&($('#aCredits').textContent=j.ai_credits);state.me.plan=j.plan;state.me.ai_credits=j.ai_credits;state.me.lead_credits=j.lead_credits;state.pageLimit=Number(j.limits?.template_page_limit||j.limits?.pages||0)||null;$('#userPlan').textContent=j.plan;const priceText=o=>o?(o.currency==='INR'?`₹${(Number(o.amount_minor)/100).toLocaleString('en-IN',{maximumFractionDigits:0})}/month`:`US$${(Number(o.amount_minor)/100).toLocaleString('en-US',{maximumFractionDigits:0})}/month`):'—';for(const plan of ['STARTER','GROWTH']){const o=offers[plan],el=$(`#${plan.toLowerCase()}RegionalPrice`);if(el&&o){const price=priceText(o);el.innerHTML=`${escapeHtml(price.replace('/month',''))}<small>/month</small>`}}const regionOffer=offers[j.plan]||offers.STARTER||j.regional_offer;if($('#regionalBillingMeta')&&regionOffer)$('#regionalBillingMeta').textContent=`${regionOffer.billing_region==='INDIA'?'India':'International'} regional pricing · Starter ${priceText(offers.STARTER)} · Growth ${priceText(offers.GROWTH)}. Checkout is recalculated and reconciled server-side.`;const publicName={FREE:'Free',STARTER:'Starter',GROWTH:'Growth',PRO:'Managed',ZYLORA:'Legacy Zylora'}[j.plan]||j.plan;if($('#currentPlanBadge'))$('#currentPlanBadge').textContent=publicName;if($('#currentPlanPrice'))$('#currentPlanPrice').textContent=['STARTER','GROWTH','ZYLORA'].includes(j.plan)&&sub?`${formatMoney(sub.billing_amount_minor,sub.billing_currency)} / month`:j.plan==='PRO'?'Managed':'Free';if($('#currentPlanMeta')){$('#currentPlanMeta').textContent=['STARTER','GROWTH','ZYLORA'].includes(j.plan)?`${sub?.billing_region||regionOffer?.billing_region||'Regional'} billing · ${j.ai_credits} AI credits · ${j.lead_credits} lead credits · unlimited AI Sales Assistant${sub?.cancel_at_period_end?' · cancellation scheduled for period end':''}.`:j.plan==='PRO'?'Sales-assisted delivery with no self-service credit wallet.':`${j.ai_credits} AI credits · ${j.lead_credits} lead credits · unlimited AI Sales Assistant.`}for(const plan of ['STARTER','GROWTH']){const btn=$(`[data-paid-plan="${plan}"]`);if(!btn)continue;const label=plan[0]+plan.slice(1).toLowerCase(),active=j.plan===plan;btn.disabled=active;btn.textContent=active?(sub?.cancel_at_period_end?'Active · cancellation scheduled':`${label} active`):(['STARTER','GROWTH','ZYLORA'].includes(j.plan)?`Switch to ${label}`:`Activate ${label}`)}renderCreditTopups(topups);const rows=$('#billingHistoryRows'),empty=$('#billingHistoryEmpty');if(rows)rows.innerHTML=(history.items||[]).map(x=>`<tr><td data-label="Reference">${escapeHtml((x.provider_payment_id||x.id||'').slice(0,22))}</td><td data-label="Date">${x.created_at?new Date(x.created_at).toLocaleDateString():'—'}</td><td data-label="Status"><span class="billing-status ${String(x.status||'').toLowerCase()}">${escapeHtml(x.status||'—')}</span></td><td data-label="Type">${escapeHtml(x.kind==='TOPUP'?x.label:(x.kind==='SUBSCRIPTION'?x.label:`${x.label} plan`))}</td><td data-label="Amount">${formatMoney(x.amount_minor,x.currency)}</td></tr>`).join('');if(empty)empty.style.display=(history.items||[]).length?'none':'grid';renderAnalytics();loadBillingRecovery()}
async function buyCreditTopup(credit_type,pack_code){try{$('#creditTopupMsg').textContent='Creating secure checkout…';const o=await api('/api/billing/credit-topups/order',{method:'POST',body:JSON.stringify({credit_type,pack_code})});if(o.provider==='mock'){const v=await api('/api/billing/credit-topups/verify',{method:'POST',body:JSON.stringify({order_id:o.order_id,payment_id:o.mock_payment_id,signature:o.mock_signature})});$('#creditTopupMsg').textContent=`Added ${o.credits} ${credit_type==='ai'?'AI':'lead'} credits.`;await loadBilling();return}await loadRazorpay();const rz=new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,order_id:o.order_id,name:'Zylora',description:`${o.credits} ${credit_type} credits`,prefill:{name:state.me.name,email:state.me.email},handler:async r=>{await api('/api/billing/credit-topups/verify',{method:'POST',body:JSON.stringify({order_id:r.razorpay_order_id,payment_id:r.razorpay_payment_id,signature:r.razorpay_signature})});$('#creditTopupMsg').textContent='Credit top-up applied.';await loadBilling()}});rz.open()}catch(e){$('#creditTopupMsg').textContent=e.message}}
async function switchFree(){try{if(['STARTER','GROWTH','ZYLORA'].includes(state.me?.plan)){await api('/api/billing/subscription/cancel',{method:'POST'});$('#billingMsg').textContent='Cancellation scheduled. Paid access remains active through the current billing period.';toast('Cancellation scheduled');await loadBilling();return}const j=await api('/api/billing/change',{method:'POST',body:JSON.stringify({plan:'FREE'})});$('#billingMsg').textContent=`Plan changed to ${j.plan}.`;await loadBilling();toast('Plan: FREE')}catch(e){$('#billingMsg').textContent=e.message}}
async function loadRazorpay(){if(window.Razorpay)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=resolve;s.onerror=()=>reject(new Error('Could not load Razorpay Checkout'));document.head.appendChild(s)})}
async function upgradePaid(plan='STARTER',waitForCompletion=false){plan=String(plan||'').toUpperCase();if(!['STARTER','GROWTH'].includes(plan)){const msg='Only Starter and Growth can be activated through self-service checkout.';$('#billingMsg').textContent=msg;return false}const label=plan[0]+plan.slice(1).toLowerCase();try{$('#billingMsg').textContent=`Creating server-priced ${label} subscription checkout…`;const idem=crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;const o=await api('/api/billing/subscription',{method:'POST',headers:{'Idempotency-Key':idem},body:JSON.stringify({plan})});if(o.already_active){$('#billingMsg').textContent=`${label} is already active.`;await loadBilling();return true}const verify=async(paymentId,signature,subscriptionId=o.subscription_id)=>{const v=await api('/api/billing/subscription/verify',{method:'POST',body:JSON.stringify({subscription_id:subscriptionId,payment_id:paymentId,signature})});$('#billingMsg').textContent=`Payment verified. ${label} is active at ${v.currency==='INR'?'₹':'US$'}${Number(v.amount_minor)/100}/month.`;await loadBilling();renderTemplates();toast(`${label} active`);return true};if(o.provider==='mock')return await verify(o.mock_payment_id,o.mock_signature,o.subscription_id);await loadRazorpay();return await new Promise(resolve=>{const rz=new Razorpay({key:o.key_id,subscription_id:o.subscription_id,name:'Zylora',description:`${label} · ${o.billing_region==='INDIA'?'India':'International'} monthly`,prefill:{name:state.me.name,email:state.me.email},handler:async r=>{try{resolve(await verify(r.razorpay_payment_id,r.razorpay_signature,r.razorpay_subscription_id||o.subscription_id))}catch(e){$('#billingMsg').textContent=e.message;resolve(false)}}});rz.on?.('payment.failed',()=>{if($('#billingMsg'))$('#billingMsg').textContent='Payment was not completed. Your entitlement has not changed.';resolve(false)});rz.open();if(!waitForCompletion)setTimeout(()=>resolve(false),0)})}catch(e){$('#billingMsg').textContent=e.message;return false}}
async function loadDomains(){const siteId=$('#domainSite').value;if(!siteId){$('#domainList').innerHTML='<p class="muted-copy">Create a website first.</p>';return}try{const r=await api(`/api/sites/${siteId}/domains`);$('#domainList').innerHTML=r.items.length?r.items.map(d=>`<div class="stack-item"><h3>${escapeHtml(d.hostname)}</h3><p>CNAME → ${escapeHtml(d.cname_target||r.cname_target||'')}</p><div class="domain-status"><span class="${d.status==='ACTIVE'?'active':''}">HOST ${escapeHtml(d.status)}</span><span class="${d.ssl_status==='ACTIVE'?'active':''}">SSL ${escapeHtml(d.ssl_status)}</span></div><div class="stack-actions"><button data-domain-refresh="${d.id}">Refresh</button><button class="danger" data-domain-delete="${d.id}">Remove</button></div></div>`).join(''):'<p class="muted-copy">No custom domains connected.</p>';$$('[data-domain-refresh]').forEach(b=>b.onclick=async()=>{try{const j=await api(`/api/domains/${b.dataset.domainRefresh}/refresh`,{method:'POST'});toast(`Domain: ${j.status} / SSL: ${j.ssl_status}`);loadDomains()}catch(e){toast(e.message)}});$$('[data-domain-delete]').forEach(b=>b.onclick=async()=>{try{await api(`/api/domains/${b.dataset.domainDelete}`,{method:'DELETE'});toast('Domain removed');loadDomains()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
